#include "logos_graph.h"
#include <algorithm>
#include <queue>
namespace logos {
static Status build_view(std::string_view id,u64 revision,ViewType vt,const Digest256&root,const std::vector<Digest256>&selected,Buffer*out,Digest256*d){LgoBuilder b{};lgo_begin(&b);lgo_add_u64(&b,F_RECORD_KIND,1);lgo_add_u64(&b,F_NODE_TYPE,(u64)NodeType::VIEW);lgo_add_utf8(&b,F_SEMANTIC_ID,id);lgo_add_u64(&b,F_REVISION,revision);lgo_add_u64(&b,F_LIFECYCLE,(u64)Lifecycle::ACTIVE);lgo_add_digest_list(&b,F_BODY_DIGEST,selected);lgo_add_digest(&b,F_GRAPH_ROOT,root);lgo_add_u64(&b,F_VIEW_TYPE,(u64)vt);return lgo_finish(&b,out,d);}static Status publish(GraphState*g,ObjectStore*s,Ledger*l,std::string_view id,ViewType vt,const Digest256&root,const std::vector<Digest256>&sel,Digest256*out){u64 rev=1;auto it=g->nodes.find(std::string(id));if(it!=g->nodes.end())rev=it->second.revision;Buffer b;Digest256 d{};auto st=build_view(id,rev,vt,root,sel,&b,&d);if(st!=Status::Ok)return st;if(it!=g->nodes.end()&&it->second.revision_digest==d){*out=d;return Status::Ok;}if(it!=g->nodes.end()){rev++;build_view(id,rev,vt,root,sel,&b,&d);}Digest256 od{};if((st=object_put(s,{b.data(),(u64)b.size()},&od))!=Status::Ok)return st;if((st=ledger_append(l,EventType::VIEW_PUBLISHED,od,id,nullptr))!=Status::Ok)return st;LglRecord r{};r.event_type=(u32)EventType::VIEW_PUBLISHED;r.payload_object_digest=od;if((st=graph_apply_event(g,s,r))!=Status::Ok)return st;*out=od;return Status::Ok;}Status compile_canon_view(GraphState*g,ObjectStore*s,Ledger*l,Digest256*out){Digest256 root{};graph_root(*g,&root);std::vector<std::pair<std::string,Digest256>>x;for(auto&kv:g->nodes){auto&id=kv.first;auto&n=kv.second;if(n.type==NodeType::PRINCIPLE){Buffer b;LgoObjectView v{};if(graph_load_node(*g,*s,id,&b,&v)!=Status::Ok)continue;u64 m{};if(lgo_get_u64(v,F_MATURITY,&m)==Status::Ok&&m>=3)x.push_back({id,n.revision_digest});}}std::sort(x.begin(),x.end(),[](auto&a,auto&b){return a.first<b.first;});std::vector<Digest256>d;for(auto&p:x)d.push_back(p.second);return publish(g,s,l,"VIEW-CANON-MEVS-001",ViewType::CANON,root,d,out);}Status compile_proof_view(GraphState*g,ObjectStore*s,Ledger*l,std::string_view start,Digest256*out){if(!g->nodes.count(std::string(start)))return Status::NodeMissing;std::set<std::string>selected{std::string(start)};std::queue<std::string>q;q.push(std::string(start));auto allowed=[](RelationCode r){return r==RelationCode::TESTS||r==RelationCode::OBSERVES||r==RelationCode::SUPPORTS||r==RelationCode::SCOPED_TO;};while(!q.empty()){auto cur=q.front();q.pop();for(auto&kv:g->edges){auto&e=kv.second;if(allowed(e.relation)&&(e.from_id==cur||e.to_id==cur)){auto other=e.from_id==cur?e.to_id:e.from_id;if(selected.insert(other).second)q.push(other);}}}for(auto&kv:g->nodes){auto&id=kv.first;auto&n=kv.second;if(n.type==NodeType::EVIDENCE){Buffer b;LgoObjectView v{};if(graph_load_node(*g,*s,id,&b,&v)!=Status::Ok)continue;std::string a,bb;if(lgo_get_utf8(v,F_REF_A_ID,&a)==Status::Ok&&lgo_get_utf8(v,F_REF_B_ID,&bb)==Status::Ok&&selected.count(a)&&selected.count(bb))selected.insert(id);}}std::vector<std::pair<std::pair<u64,std::string>,Digest256>>x;for(auto&id:selected){auto&n=g->nodes[id];x.push_back({{(u64)n.type,id},n.revision_digest});}std::sort(x.begin(),x.end(),[](auto&a,auto&b){return a.first<b.first;});std::vector<Digest256>d;for(auto&p:x)d.push_back(p.second);Digest256 root{};graph_root(*g,&root);return publish(g,s,l,"VIEW-PROOF-MEVS-001",ViewType::PROOF,root,d,out);}
}
